<?php declare(strict_types=1); ?>
<div class="grid-2"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Record-scoped communication</span><h2>Send message</h2></div></header><?php if(supplier_portal_can($account,'message')): ?><form class="form-grid" method="post" action="<?= h(root_url('supplier-portal/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="send_message"><input type="hidden" name="return_tab" value="messages"><label><span>Record type</span><select name="entity_type"><option value="supplier">Supplier</option><option value="purchase_order">Purchase order</option><option value="invoice">Invoice</option><option value="quality">Quality</option><option value="sourcing">Sourcing</option></select></label><label><span>Record ID</span><input type="number" name="entity_id" value="<?= (int)$account['supplier_id'] ?>"></label><label class="span-2"><span>Subject</span><input name="subject" required></label><label class="span-2"><span>Message</span><textarea name="message_body" required></textarea></label><div class="span-2"><button class="button primary">Send message</button></div></form><?php endif; ?></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Supplier-visible history</span><h2>Messages</h2></div></header><div class="record-list"><?php foreach($messages as $message): ?><article class="record-card"><header><div><strong><?= h($message['subject']) ?></strong><small><?= h(status_label($message['direction'])) ?> · <?= h(status_label($message['entity_type'])) ?> #<?= (int)$message['entity_id'] ?></small></div><span class="status <?= h($message['status']) ?>"><?= h(status_label($message['status'])) ?></span></header><p><?= h($message['message_body']) ?></p><?php if($message['direction']==='internal_to_supplier'&&$message['status']==='open'): ?><form method="post" action="<?= h(root_url('supplier-portal/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="ack_message"><input type="hidden" name="return_tab" value="messages"><input type="hidden" name="message_id" value="<?= (int)$message['id'] ?>"><button class="button secondary">Acknowledge message</button></form><?php endif; ?></article><?php endforeach; ?></div></section></div>
